function changeSvgs(arr) {
  function updateSVGs() {
    for (const s of arr) {
      const [selector, pathD, viewBox] = s;
      const svgs = document.querySelectorAll(selector);
      svgs.forEach((svg) => {
        const button = svg.closest('button');
        const label = button?.getAttribute('aria-label') || '';
        const testId = button?.getAttribute('data-testid') || '';

        // STRICT TARGETING: Only for Like, Save, Add, Heart
        const isTarget =
          label.includes('Save') ||
          label.includes('Add') ||
          label.includes('Like') ||
          label.includes('playlist') ||
          testId.includes('like') ||
          testId.includes('add');

        // STRICT BLOCKING: No navigation, options, more, connect, share
        const isBlocked =
          label.includes('Previous') ||
          label.includes('Next') ||
          label.includes('Skip') ||
          label.includes('Options') ||
          label.includes('More') ||
          label.includes('Connect') ||
          label.includes('Share') ||
          label.includes('Volume') ||
          label.includes('devices') ||
          label.includes('Play');

        if (isTarget && !isBlocked) {
          svg.setAttribute('viewBox', viewBox);
          const path = svg.querySelector('path');
          if (path) path.setAttribute('d', pathD);
        }
      });
    }

    // Surgical Liked Songs Art Swap (JS side for placeholder div)
    const placeholders = document.querySelectorAll(
      '[aria-label="Liked Songs"].x-entityImage-imagePlaceholder, [aria-label="Liked Songs"] .x-entityImage-imagePlaceholder',
    );
    placeholders.forEach((el) => {
      if (el.style.backgroundImage !== 'url("data:image/png;base64,")') {
        el.style.backgroundImage = 'url("data:image/png;base64,")';
        el.style.backgroundSize = 'cover';
        el.style.backgroundPosition = 'center';
        const innerSvg = el.querySelector('svg');
        if (innerSvg) innerSvg.style.display = 'none';
      }
    });
  }

  const observer = new MutationObserver(() => {
    updateSVGs();
  });

  observer.observe(document.body, {
    childList: true,
    subtree: true
  });

  updateSVGs();
}

/**
 * @param {(els: HTMLElement[]) => void} func 
 */
function waitForElement(els, func, timeout = 100) {
  const queries = els.map((el) => document.querySelector(el));
  if (queries.every((a) => a)) {
    func(queries);
  } else if (timeout > 0) {
    setTimeout(waitForElement, 300, els, func, --timeout);
  }
}

